'use strict';

// MODULES //

var bench = require( '@stdlib/bench-harness' );
var isBoolean = require( '@stdlib/assert-is-boolean' ).isPrimitive;
var pkg = require( './../package.json' ).name;
var isSameValueZero = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var values;
	var bool;
	var v;
	var i;

	values = [
		5.0,
		3.14,
		NaN,
		-0.0,
		0.0,
		-1.0
	];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = values[ i%values.length ];
		bool = isSameValueZero( v, v );
		if ( typeof bool !== 'boolean' ) {
			b.fail( 'should return a boolean' );
		}
	}
	b.toc();
	if ( !isBoolean( bool ) ) {
		b.fail( 'should return a boolean' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});","lineStart":1,"lineEnd":60,"totalLines":60,"truncated":false}},"title":"repos/pc-lib-3456/number-float64-base-assert-is-same-value-zero/benchmark/benchmark.js","time":{"start":1783263556768,"end":1783263556780}},"id":"prt_f32ca736d001EV8c9XSUOocff0","sessionID":"ses_0cd36154fffeqARP6quSCX17nW","messageID":"msg_f32ca5fe6001586PuskOjtgnvD"}}

